// Starts the screen of an application generated by Clarity, bound to its
// backend; it reads the windows Generate wrote as markup (DESIGN 7.8).
import { mount } from "svelte";
import Runtime from "./Runtime.svelte";
import "../screen/render.css";
import { followSystemScheme } from "../screen/scheme.svelte.ts";
import { pageMenuOff } from "../frame/pageMenu.ts";

/** Shows the application in the page's #app element. */
export function startScreen() {
  followSystemScheme();
  pageMenuOff();
  const target = document.getElementById("app");
  if (!target) throw new Error("missing #app element");
  return mount(Runtime, { target });
}
